type Leaf = { value: int, doubled = value * 2 }
type Item = { value: int, increment?: int = value + 1, leaf?: Leaf = { value: increment }, positive = [value, increment] |> std.array.filter((x) => x > 0), label = "${leaf.doubled}" }
input batch: Item[]
output result: int = std.array.sum([r.leaf.doubled for r in batch])

type Item = { value: int, result = value + 7, optional?: int, chosen = optional ?? result }
func make(n: int): Item = { value: n }
input values: int[]
output batch: Item[] = [make(n) for n in values]
